body.onloadscript:

	selfObj._dndUnloadModule();

	$.extend(true, Sepoa.params, {selfApproval: false, userSearchCache: false, approverInsertPos: "top"});
    var popup = $sObject.$popup = new SepoaContractApprovalPopup(container, Sepoa.params);
    popup.tabbar.tabbar1.tabbarObj.setSizes();
    popup.tabbar.tabbar2.tabbarObj.setSizes();

    popup.tabbar.tabbar1.tabbarObj.tabs("chart").setText("검색")
    popup.tabbar.tabbar1.tabbarObj.tabs("preset").hide();
    popup.tabbar.tabbar2.tabbarObj.tabs("referer").hide();
    $(popup.base.getElementsByClassName("set-approval-button-save-preset")[0]).hide();
    popup.base.getElementsByClassName("set-approval-button-approvalLine")[0].innerText = "상신";
    $(popup.tabbar.tabbar2.tabbarObj.tabs("approval").cell.getElementsByClassName("set-approval-content")).find("select.table-body-item-inner.table-body-item-center").attr("disabled", "true");
